// GERADO por scratch/_iconsbuild.py a partir do lucide-react.
// Ícones de linha dos formulários impressos, em PNG base64 para o DOCX
// não depender de rede (o gerador roda no browser e no teste em node).

const decode = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

const RAW: Record<string, string> = {
  user: "",
  phone: "",
  mail: "",
  badge: "",
  file: "",
  briefcase: "",
  level: "",
  pin: "",
  building: "",
  money: "",
  gift: "",
  userCheck: "",
  calendar: "",
  shield: "",
  message: "",
  clipboard: "",
};

export type MpIcon = keyof typeof RAW;

/** Bytes PNG do ícone, decodificados sob demanda. */
export const mpIcon = (name: MpIcon): Uint8Array => decode(RAW[name]);
